{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The following criteria were used to determine eligibility for inclusion in this study: (1) Clinical trials and observational studies published before November 28, 2022; (2) Participants diagnosed with NSTI (or NF or FG); (3) Studies that compared the use of HBO with no use of HBO; (4) Studies that reported at least one outcome of interest. The following types of studies were excluded: (1) Conference abstracts, reviews, animal studies, case reports, editorials, letters, etc.; (2) Duplicate studies; (2) Full text unavailable; (3) Studies from which data could not be extracted; (4) Studies with inappropriate outcomes; (5) Studies with low sample sizes (total n < 10).",
      "reason": "The eligibility text specifies study designs (clinical trials and observational), date limit, participant diagnoses, comparator (HBO vs no HBO), required outcomes, and lists excluded study types and sample-size threshold, covering study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Clinical trials and observational studies published before November 28, 2022; ... The following types of studies were excluded: (1) Conference abstracts, reviews, animal studies, case reports, editorials, letters, etc.; ...",
      "reason": "The review specifies a cut-off publication date and excludes certain report types (conference abstracts, reviews, etc.), addressing dissemination year and publication/report status, but no eligibility restriction by language is stated."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "Studies that reported at least one outcome of interest. ... (3) Studies from which data could not be extracted; (4) Studies with inappropriate outcomes;",
      "reason": "The manuscript does not explicitly distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported; the statements do not clearly separate 'not measured' versus 'not reported'."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "(3) Studies that compared the use of HBO with no use of HBO;",
      "reason": "The planned grouping for synthesis is specified as HBO versus no HBO (the comparator used across included studies); subgroup analyses by pathological entity are also described (text_14), linking groups to the review comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "The following types of studies were excluded: (1) Conference abstracts, reviews, animal studies, case reports, editorials, letters, etc.; ... (5) Studies with low sample sizes (total n < 10).",
      "reason": "While notable restrictions are listed (e.g. excluding small sample sizes and certain publication types), no rationale is provided explaining why these specific restrictions were imposed."
    }
  ],
  "confidence": 85
}

